printf '%s  %s\n' '953d54188a556aef177008a34c21482c9690de573aa0a61bd57067632a9c4a70' "$staging/project.tar.gz" | sha256sum --check --status
mkdir -m700 "$staging/project"
tar -xzf "$staging/project.tar.gz" -C "$staging/project"
[[ -f "$staging/project/install.sh" && -f "$staging/project/linux/setup.sh" ]] || { echo '安装包不完整。' >&2; exit 1; }
if [[ -d "$target" ]]; then
  previous="$(mktemp -d /opt/agent-node-backup.XXXXXX)"
  mv -T "$target" "$previous/project"
  echo "旧程序备份：$previous/project"
fi
mv -Tn "$staging/project" "$target"
[[ ! -d "$staging/project" ]] || { echo '目标目录已被其他进程创建；未覆盖。' >&2; exit 1; }
bash "$target/install.sh" "$@"
finished=1
